import { env } from "../config/env";

/** Public Storage bucket for project screenshots (readable by anyone, writable only by this API). */
export const PROJECT_IMAGE_BUCKET = "project-images";

/**
 * Public address of a stored screenshot. Names are generated by the API and
 * constrained by a CHECK in the database, so they're always URL-safe.
 */
export function projectImageUrl(path: string | null | undefined) {
  const { supabaseUrl } = env();
  return path && supabaseUrl ? `${supabaseUrl.replace(/\/+$/, "")}/storage/v1/object/public/${PROJECT_IMAGE_BUCKET}/${path}` : null;
}
